WITH enriched AS (SELECT s.*, o.order_date FROM order_items s LEFT JOIN orders o ON s.order_id = o.id), metrics AS (SELECT *, AVG(quantity) OVER (PARTITION BY order_id, product_id ORDER BY order_date, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS quantity_avg_5_prior, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_id), 4) AS unit_price_share, MAX(unit_price) OVER (PARTITION BY order_id) AS order_id_max_unit_price, CORR(quantity, unit_price) OVER (PARTITION BY order_id) AS corr_quantity_unit_price, NTILE(5) OVER (PARTITION BY order_id, product_id ORDER BY unit_price DESC, id) AS unit_price_bucket FROM enriched), with_dims AS (SELECT e.*, b.shipping_fee, b.amount, b.channel FROM metrics e LEFT JOIN orders b ON e.order_id = b.id), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY order_id_max_unit_price DESC NULLS FIRST, id) AS rank_in_group FROM with_dims) ranked WHERE rank_in_group = 1), joined AS (SELECT src.*, p.discount, p.channel AS order_channel FROM deduped src INNER JOIN orders p ON src.order_id = p.id), with_windows AS (SELECT *, FIRST_VALUE(shipping_fee, TRUE) OVER (PARTITION BY order_id, order_channel ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_shipping_fee, LAG(unit_price_share, 1) OVER (ORDER BY rank_in_group, id) AS prev_unit_price_share, NTILE(5) OVER (PARTITION BY order_id, channel ORDER BY quantity, id) AS quantity_bucket FROM joined), stats AS (SELECT CASE WHEN first_known_shipping_fee >= 39 THEN 'PREMIUM' ELSE 'STANDARD' END AS first_known_shipping_fee_tier, DATE_TRUNC('WEEK', order_date) AS week_start, COUNT(*) FILTER (WHERE channel = 'store') AS store_rows, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT channel) AS distinct_channels FROM with_windows GROUP BY ROLLUP (CASE WHEN first_known_shipping_fee >= 39 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', order_date))) SELECT first_known_shipping_fee_tier, week_start, store_rows, distinct_ids FROM stats ORDER BY store_rows NULLS FIRST;
